// Auto-generated by Cloud Payments. Do not edit — regenerated on enable.

import type {
  CheckoutOrder,
  CheckoutOrderLine,
  CheckoutOrderRecurring,
  CheckoutOrderTotals,
} from "./PaymentCheckoutBlock";

const url = import.meta.env["VITE_PAYMENT_CHECKOUT_URL"] ?? "";
if (!url) {
  console.warn("VITE_PAYMENT_CHECKOUT_URL is not set — payment checkout will not load.");
}

export const checkoutScriptUrl = url;

/** Dynamic import of the hosted checkout ES module (requires CORS on the CDN). */
export async function importCheckoutSdk<T = Record<string, unknown>>(): Promise<T> {
  if (!checkoutScriptUrl) {
    throw new Error("Payment checkout URL is not configured.");
  }
  return import(/* @vite-ignore */ checkoutScriptUrl) as Promise<T>;
}

/**
 * True when this page load is the buyer coming back from a redirect payment
 * method (iDEAL, Klarna, Cash App, ...). A checkout shown in a modal must open
 * again on such a load so the block can finish the payment. False on the server.
 */
export function isCheckoutReturn(): boolean {
  if (typeof window === "undefined") return false;
  const params = new URLSearchParams(window.location.search);
  return Boolean(params.get("payment_intent") || params.get("setup_intent"));
}

// ── The paid order, for a thank-you page ────────────────────────────────────
// The checkout writes it to sessionStorage once an order is paid, without the
// buyer. Storage is anyone's to write, so every field is checked and anything
// malformed reads as no order.

type Fields = Record<string, unknown>;

const isFields = (v: unknown): v is Fields => typeof v === "object" && v !== null && !Array.isArray(v);
const isNum = (v: unknown): v is number => typeof v === "number" && Number.isFinite(v);
const optNum = (o: Fields, key: string): Fields => (isNum(o[key]) ? { [key]: o[key] } : {});

function readRecurring(v: unknown): CheckoutOrderRecurring | null {
  if (!isFields(v) || typeof v["interval"] !== "string" || !isNum(v["intervalCount"])) return null;
  return {
    interval: v["interval"],
    intervalCount: v["intervalCount"],
    ...optNum(v, "trialDays"),
    ...optNum(v, "setupFee"),
    ...optNum(v, "totalCycles"),
  };
}

function readLine(v: unknown): CheckoutOrderLine | null {
  if (!isFields(v)) return null;
  const productId = v["productId"];
  const priceId = v["priceId"];
  const name = v["name"];
  const unitAmount = v["unitAmount"];
  const quantity = v["quantity"];
  if (typeof productId !== "string" || typeof priceId !== "string" || typeof name !== "string") return null;
  if (!isNum(unitAmount) || !isNum(quantity)) return null;
  const recurring = v["recurring"] === undefined ? undefined : readRecurring(v["recurring"]);
  if (recurring === null) return null;
  const image = v["image"];
  return {
    productId,
    priceId,
    name,
    image: typeof image === "string" ? image : "",
    unitAmount,
    quantity,
    ...(recurring ? { recurring } : {}),
  };
}

function readTotals(v: unknown): CheckoutOrderTotals | null {
  if (!isFields(v)) return null;
  const subtotal = v["subtotal"];
  const totalDueToday = v["totalDueToday"];
  const rawTaxes = v["taxes"];
  if (!isNum(subtotal) || !isNum(totalDueToday) || !Array.isArray(rawTaxes)) return null;
  const taxes: CheckoutOrderTotals["taxes"] = [];
  for (const t of rawTaxes) {
    if (!isFields(t) || typeof t["name"] !== "string" || !isNum(t["rate"]) || !isNum(t["amount"])) return null;
    taxes.push({ name: t["name"], rate: t["rate"], amount: t["amount"], inclusive: t["inclusive"] === true });
  }
  const r = v["recurring"];
  const recurring =
    isFields(r) && isNum(r["amount"]) && typeof r["interval"] === "string" && isNum(r["intervalCount"])
      ? { recurring: { amount: r["amount"], interval: r["interval"], intervalCount: r["intervalCount"] } }
      : {};
  const couponCode = v["couponCode"];
  return {
    subtotal,
    ...optNum(v, "discount"),
    ...(typeof couponCode === "string" && couponCode ? { couponCode } : {}),
    taxes,
    ...optNum(v, "tax"),
    ...optNum(v, "inclusiveTax"),
    ...optNum(v, "deliveryCost"),
    ...optNum(v, "deliveryTax"),
    ...optNum(v, "additionalCharge"),
    ...optNum(v, "giftCard"),
    totalDueToday,
    ...recurring,
  };
}

/**
 * The order the buyer just paid, for a thank-you page; null when there is
 * none (a direct visit, another tab, or storage refused) or on the server.
 * Read it after hydration. It never includes the buyer.
 */
export function readCheckoutOrder(): CheckoutOrder | null {
  if (typeof window === "undefined") return null;
  let parsed: unknown;
  try {
    const raw = window.sessionStorage.getItem("vibe.checkout.order-summary.v1");
    if (!raw) return null;
    parsed = JSON.parse(raw);
  } catch {
    return null;
  }
  if (!isFields(parsed)) return null;
  const orderId = parsed["orderId"];
  const currency = parsed["currency"];
  const amount = parsed["amount"];
  const rawLines = parsed["lines"];
  if (typeof orderId !== "string" || !orderId || typeof currency !== "string" || !isNum(amount)) return null;
  if (!Array.isArray(rawLines)) return null;
  const lines: CheckoutOrderLine[] = [];
  for (const raw of rawLines) {
    const line = readLine(raw);
    if (!line) return null;
    lines.push(line);
  }
  const totals = readTotals(parsed["totals"]);
  if (!totals) return null;
  return { orderId, currency, amount, lines, totals };
}
